def category(product):
    p = clean_text(product)
    if p == "":
        return "Unknown"
    if p in ("Laptop", "Monitor", "Keyboard", "Mouse"):
        return "Computer"
    if p == "Headset":
        return "Audio"
    return "Other"

counts = {}
for r in sales:
    cat = category(r["Product"])
    counts[cat] = counts.get(cat, 0) + 1

cshare = round(counts["Computer"] / len(sales), 4)
